  const scoped = [issueLabels, attachments, comments, notifications, notificationPreferences, activityEvents, invoices, subscriptions, webhookDeliveries, webhookEndpoints, searchIndex, rateLimitBuckets, projectMembers, issues, labels, projects, invitations, members, organizationUsage] as const;
  db.transaction((tx) => {
    tx.update(sessions).set({ activeOrgId: null }).where(eq(sessions.activeOrgId, orgId)).run();
