export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }
  assertNotArchived("Organization", input.orgId, org);
  const archived = await orgRepo.archiveOrg(input.orgId);
  await emit("organization.deleted", { ...envelope(input.orgId, actor.userId), slug: org.slug });
  return archived;
}

export async function restoreOrganization(userId: UserId, orgId: OrgId): Promise<Organization> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) throw new NotFoundError("Organization", orgId);
  const member = await memberRepo.findMember(orgId, userId);
  if (!member) throw new NotFoundError("Organization", orgId);
  if (org.archivedAt === null) return org;
  const deadline = Date.parse(org.archivedAt) + DELETED_WORKSPACE_RETENTION_DAYS * 24 * 60 * 60 * 1000;
  if (Date.now() >= deadline) throw new NotFoundError("Organization", orgId);
  assertCan({ userId, orgId, role: member.role }, "org:restore", orgResource(orgId));
  const restored = await orgRepo.restoreOrg(orgId);
  await emit("organization.restored", { ...envelope(orgId, userId), slug: org.slug });
  return restored;
}

